PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?person ?birthDate WHERE {
  VALUES ?person { dbr:Levon_Julfalakyan dbr:Charlotte_Spurkeland }
  OPTIONAL { ?person dbp:birthDate ?b1 . }
  OPTIONAL { ?person dbo:birthDate ?b2 . }
  BIND (COALESCE(?b1, ?b2) AS ?birthDate)
}
LIMIT 100

